<?php
class CC_Admin { public static function init(){add_action('admin_menu',function(){add_options_page('مشارکت مردمی','مشارکت مردمی','manage_options','city-contrib',array(__CLASS__,'page'));});add_action('admin_init',function(){register_setting('cc_settings','cc_sms_endpoint',array('sanitize_callback'=>'esc_url_raw'));register_setting('cc_settings','cc_sms_key');register_setting('cc_settings','cc_sms_sender',array('sanitize_callback'=>'sanitize_text_field'));});} public static function page(){if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>مشارکت مردمی شهر من</h1><form method="post" action="options.php">';settings_fields('cc_settings');echo '<table class="form-table"><tr><th>آدرس API پیامک</th><td><input class="regular-text" name="cc_sms_endpoint" value="'.esc_attr(get_option('cc_sms_endpoint','')).'"></td></tr><tr><th>کلید API</th><td><input class="regular-text" type="password" name="cc_sms_key" value="'.esc_attr(get_option('cc_sms_key','')).'"></td></tr><tr><th>فرستنده</th><td><input class="regular-text" name="cc_sms_sender" value="'.esc_attr(get_option('cc_sms_sender','')).'"></td></tr></table>';submit_button('ذخیره تنظیمات');echo '</form><p>در حالت توسعه، اگر API خالی باشد کد OTP فقط در debug.log ثبت می‌شود.</p></div>';}}
